#include <kin/ecs/component.hpp>
#include <algorithm>
#include <cassert>
#include <chrono>
#include <cstdlib>
#include <iostream>
#include <new>
#include <string>
#include <vector>
namespace { thread_local bool count_new = false; thread_local std::size_t allocations = 0, allocated_bytes = 0; }
void* operator new(std::size_t size) {
    if (void* value = std::malloc(size ? size : 1)) {
        if (count_new) { ++allocations; allocated_bytes += size; }
        return value;
    }
    throw std::bad_alloc{};
}
void operator delete(void* value) noexcept { std::free(value); }
void operator delete(void* value, std::size_t) noexcept { std::free(value); }
struct FieldCallbackProbe { kin::i32 value = 7; struct Nested { kin::f32 value = 2; } nested; std::string text = "hello"; };
int main() {
    kin::EcsWorld world;
    auto builder = world.components().native<FieldCallbackProbe>("FieldCallbackProbe");
    count_new = true;
    for (int i=0;i<1000;++i) builder.field("f"+std::to_string(i), &FieldCallbackProbe::value);
    count_new = false;
    const auto field_allocations=allocations, field_bytes=allocated_bytes;
    builder.field("nested", &FieldCallbackProbe::nested, &FieldCallbackProbe::Nested::value)
        .field("text", &FieldCallbackProbe::text);
    auto entity=world.entity("probe").set(FieldCallbackProbe{});
    assert(world.components().patch_field(entity,"FieldCallbackProbe","f0",kin::i32{19}));
    assert(world.components().patch_field(entity,"FieldCallbackProbe","nested",kin::f32{4}));
    assert(world.components().patch_field(entity,"FieldCallbackProbe","text",std::string{"changed"}));
    assert(entity.get<FieldCallbackProbe>()->value==19 && entity.get<FieldCallbackProbe>()->nested.value==4 && entity.get<FieldCallbackProbe>()->text=="changed");
    std::vector<double> samples; kin::i64 checksum=0;
    for(int sample=0;sample<13;++sample) {
        auto start=std::chrono::steady_clock::now();
        for(int i=0;i<1000;++i) {
            const bool found=world.components().visit_fields(entity,"FieldCallbackProbe",[&](std::string_view,kin::ComponentFieldKind kind,const kin::ComponentFieldValue& value) { if(kind==kin::ComponentFieldKind::I32) checksum+=std::get<kin::i32>(value); });
            assert(found);
        }
        if(sample>=3) samples.push_back(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());
    }
    assert(checksum==13LL*1000*1000*19); std::sort(samples.begin(),samples.end());
    std::cout << "{\"field_count\":1000,\"registration_new_calls\":" << field_allocations << ",\"registration_new_bytes\":" << field_bytes << ",\"visit_million_fields_median_ms\":" << samples[samples.size()/2] << ",\"checksum\":" << checksum << "}\n";
}

